def calculate_material_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.supercells import get_sc_fromstruct, _ase_cubic
    from pymatgen.core.structure import StructureError
    import os

    # Define file path
    file_path = os.path.join("tool_source_code", "pymatgen-analysis-defects", "tests", "test_files")

    # Initialize result dictionary
    results = {
        "supercell_size_constraint": None,
        "supercell_generation_failure": None
    }

    try:
        # Read the GaN structure from file
        gan_struct = Structure.from_file(os.path.join(file_path, "GaN.vasp"))

        # Check supercell size constraint
        try:
            sc_mat = _ase_cubic(gan_struct, min_atoms=4, max_atoms=8, min_length=1.0)
            sc = gan_struct * sc_mat
            results["supercell_size_constraint"] = 4 <= sc.num_sites <= 8
        except Exception:
            results["supercell_size_constraint"] = False

        # Check supercell generation failure
        try:
            sc_mat = _ase_cubic(gan_struct, min_atoms=4, max_atoms=8, min_length=10.0)
            sc = gan_struct * sc_mat
            results["supercell_generation_failure"] = False
        except RuntimeError:
            results["supercell_generation_failure"] = True

    except Exception as e:
        # If any error occurs, set all results to None
        results = {key: None for key in results}

    return results

def calculate_material_properties():
    """
    Calculate material properties using Pymatgen.

    Returns:
        dict: A dictionary mapping property names to their computed values.
    """
    test_dir = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")

    def gan_struct(test_dir):
        return Structure.from_file(test_dir / "GaN.vasp")

    def data_Mg_Ga(test_dir):
        root_dir = test_dir / "Mg_Ga"
        data = defaultdict(dict)
        for fold in root_dir.glob("./*"):
            if not fold.is_dir():
                continue
            data[fold.name] = {
                "vasprun": Vasprun(fold / "vasprun.xml.gz"),
                "locpot": Locpot.from_file(fold / "LOCPOT.gz"),
            }
        return data

    def defect_Mg_Ga(gan_struct):
        ga_site = gan_struct[0]
        mg_site = PeriodicSite(Specie("Mg"), ga_site.frac_coords, gan_struct.lattice)
        return Substitution(gan_struct, mg_site)

    def defect_entries_and_plot_data_Mg_Ga(data_Mg_Ga, defect_Mg_Ga):
        bulk_locpot = data_Mg_Ga["bulk_sc"]["locpot"]

        def get_data(q):
            computed_entry = data_Mg_Ga[f"q={q}"]["vasprun"].get_computed_entry(
                inc_structure=True
            )
            defect_locpot = data_Mg_Ga[f"q={q}"]["locpot"]

            def_entry = DefectEntry(
                defect=defect_Mg_Ga, charge_state=q, sc_entry=computed_entry
            )
            frey_summary = def_entry.get_freysoldt_correction(
                defect_locpot=defect_locpot, bulk_locpot=bulk_locpot, dielectric=14
            )
            return def_entry, frey_summary

        defect_entries = dict()
        plot_data = dict()
        for qq in [-2, -1, 0, 1]:
            defect_entry, frey_summary = get_data(qq)
            defect_entries[qq] = defect_entry
            plot_data[qq] = frey_summary.metadata["plot_data"]
        return defect_entries, plot_data

    def stable_entries_Mg_Ga_N(test_dir):
        return loadfn(test_dir / "stable_entries_Mg_Ga_N.json")

    def formation_energy_diagram(
        data_Mg_Ga, defect_entries_and_plot_data_Mg_Ga, stable_entries_Mg_Ga_N):
        bulk_vasprun = data_Mg_Ga["bulk_sc"]["vasprun"]
        bulk_bs = bulk_vasprun.get_band_structure()
        vbm = bulk_bs.get_vbm()["energy"]
        bulk_entry = bulk_vasprun.get_computed_entry(inc_structure=False)
        defect_entries, _ = defect_entries_and_plot_data_Mg_Ga

        def_ent_list = list(defect_entries.values())
        atomic_entries = list(
            filter(lambda x: len(x.composition.elements) == 1, stable_entries_Mg_Ga_N)
        )
        pd = PhaseDiagram(stable_entries_Mg_Ga_N)
        fed = FormationEnergyDiagram.with_atomic_entries(
            defect_entries=def_ent_list,
            atomic_entries=atomic_entries,
            vbm=vbm,
            inc_inf_values=False,
            phase_diagram=pd,
            bulk_entry=bulk_entry,
        )
        return fed

    try:
        gan_structure = gan_struct(test_dir)
        data_mg_ga = data_Mg_Ga(test_dir)
        defect_mg_ga = defect_Mg_Ga(gan_structure)
        defect_entries, _ = defect_entries_and_plot_data_Mg_Ga(data_mg_ga, defect_mg_ga)
        stable_entries = stable_entries_Mg_Ga_N(test_dir)
        fed = formation_energy_diagram(data_mg_ga, defect_entries, stable_entries)

        cp_at_point = {}
        for chempot_limit in fed.chempot_limits:
            competing_phases = set()
            for entry in stable_entries:
                if entry not in fed.stable_entries:
                    competing_phases.add(entry.name)
            cp_key = ", ".join(f"{k}:{v:.2f}" for k, v in chempot_limit.items())
            cp_at_point[cp_key] = competing_phases

        return {"competing_phases_at_chempot_limits": cp_at_point}

    except Exception as e:
        return {"competing_phases_at_chempot_limits": None}

def calculate_material_properties():
    """
    Calculate material properties using Pymatgen.

    Returns:
        dict: A dictionary containing the calculated properties:
            - 'freysoldt_correction': The Freysoldt correction energy (float).
            - 'potential_alignment_consistency': Consistency check for potential alignment (bool).
            - 'energy_difference': Energy difference between defect and bulk supercells (float).
    """
    test_dir = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")

    def gan_struct(test_dir):
        return Structure.from_file(test_dir / "GaN.vasp")

    def defect_Mg_Ga(gan_struct):
        ga_site = gan_struct[0]
        mg_site = PeriodicSite(Specie("Mg"), ga_site.frac_coords, gan_struct.lattice)
        return Substitution(gan_struct, mg_site)

    def data_Mg_Ga(test_dir):
        root_dir = test_dir / "Mg_Ga"
        data = defaultdict(dict)
        for fold in root_dir.glob("./*"):
            if not fold.is_dir():
                continue
            data[fold.name] = {
                "vasprun": Vasprun(fold / "vasprun.xml.gz"),
                "locpot": Locpot.from_file(fold / "LOCPOT.gz"),
            }
        return data

    try:
        gan_structure = gan_struct(test_dir)
        defect = defect_Mg_Ga(gan_structure)
        data = data_Mg_Ga(test_dir)

        bulk_locpot = data["bulk_sc"]["locpot"]
        bulk_vasprun = data["bulk_sc"]["vasprun"]
        bulk_entry = bulk_vasprun.get_computed_entry(inc_structure=False)

        defect_entries = {}
        plot_data = {}

        for q in [-2, -1, 0, 1]:
            computed_entry = data[f"q={q}"]["vasprun"].get_computed_entry(inc_structure=True)
            defect_locpot = data[f"q={q}"]["locpot"]

            def_entry = DefectEntry(defect=defect, charge_state=q, sc_entry=computed_entry)
            frey_summary = get_freysoldt_correction(
                q=q, dielectric=14, defect_locpot=defect_locpot, bulk_locpot=bulk_locpot
            )
            def_entry.corrections_metadata = {"freysoldt": frey_summary.metadata}
            defect_entries[q] = def_entry
            plot_data[q] = frey_summary.metadata["plot_data"]

        def_entry = defect_entries[0]
        def_entry.bulk_entry = bulk_entry

        # Calculate freysoldt_correction
        freysoldt_correction = frey_summary.correction_energy

        # Calculate potential_alignment_consistency
        try:
            vr1 = np.array(plot_data[0][1]["pot_plot_data"])
            vr2 = np.array(defect_entries[0].corrections_metadata["freysoldt"]["plot_data"][1]["pot_plot_data"])
            potential_alignment_consistency = np.allclose(vr1, vr2)
        except Exception:
            potential_alignment_consistency = None

        # Calculate energy_difference
        try:
            energy_difference = def_entry.sc_entry.energy - bulk_entry.energy
        except Exception:
            energy_difference = None

        return {
            "freysoldt_correction": freysoldt_correction,
            "potential_alignment_consistency": potential_alignment_consistency,
            "energy_difference": energy_difference
        }

    except Exception as e:
        return {
            "freysoldt_correction": None,
            "potential_alignment_consistency": None,
            "energy_difference": None
        }

