        properties["defect_fpos_modified"] = None

    try:
        inter2.user_charge_states = [-100, 102]
        properties["user_defined_charge_states"] = inter2.user_charge_states
    except Exception:
        properties["user_defined_charge_states"] = None

    return properties

def calculate_material_properties():
    """
    Calculate material properties related to defects in a GaN structure.

    Returns:
        dict: A dictionary containing the calculated properties:
            - 'defect_type': bool, True if all generated defects are of type Substitution, else False.
            - 'replaced_atoms_set_1': set, Set of atoms replaced in the structure with substitution {"Ga": ["Mg", "Ca"]}.
            - 'replaced_atoms_set_2': set, Set of atoms replaced in the structure with substitution {"Ga": "Mg"}.
    """
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.generators import generate_all_native_defects
    from pymatgen.analysis.defects.core import update_structure
    from pymatgen.analysis.defects.core import DefectType
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")
    gan_struct = Structure.from_file(file_path / "GaN.vasp")

    properties = {
        "defect_type": None,
        "replaced_atoms_set_1": None,
        "replaced_atoms_set_2": None
    }

    try:
        # Check if all generated defects are of type Substitution
        defects = list(generate_all_native_defects(gan_struct))
        properties["defect_type"] = all(defect.defect_type == "substitution" for defect in defects)
    except Exception:
        properties["defect_type"] = None

    try:
        # Verify the set of atoms that have been substituted in the structure
        substitution_1 = {"Ga": ["Mg", "Ca"]}
        replaced_atoms_set_1 = set()
        for site in gan_struct.sites:
            if site.species_string == "Ga":
                for new_element in substitution_1["Ga"]:
                    update_structure(gan_struct, site, DefectType.Substitution)
                    replaced_atoms_set_1.add(new_element)
        properties["replaced_atoms_set_1"] = replaced_atoms_set_1
    except Exception:
        properties["replaced_atoms_set_1"] = None

    try:
        # Verify the set of atoms that have been substituted in the structure
        substitution_2 = {"Ga": "Mg"}
        replaced_atoms_set_2 = set()
        for site in gan_struct.sites:
            if site.species_string == "Ga":
                update_structure(gan_struct, site, DefectType.Substitution)
                replaced_atoms_set_2.add(substitution_2["Ga"])
        properties["replaced_atoms_set_2"] = replaced_atoms_set_2
    except Exception:
        properties["replaced_atoms_set_2"] = None

    return properties
